window.SBS_DATA = {"track":{"id":"git","page":"git.html","nav":"Git","langs":["git"],"default_langs":["git"]},"concepts":[{"id":"init-status","level":"intro","topic":"Basics","title":"Start a repository"},{"id":"add-commit","level":"intro","topic":"Basics","title":"Stage and commit"},{"id":"log","level":"intro","topic":"History","title":"Read the history"},{"id":"diff","level":"intro","topic":"History","title":"See what changed"},{"id":"gitignore","level":"intro","topic":"Basics","title":"Ignore files"},{"id":"undo-working","level":"intro","topic":"Undo","title":"Undo changes you have not committed"},{"id":"branches","level":"intermediate","topic":"Branches","title":"Create and switch branches"},{"id":"merge","level":"intermediate","topic":"Branches","title":"Merge a branch"},{"id":"merge-conflict","level":"intermediate","topic":"Branches","title":"Resolve a merge conflict"},{"id":"clone-remote","level":"intermediate","topic":"Remotes","title":"Clone and remotes"},{"id":"push-pull","level":"intermediate","topic":"Remotes","title":"Push and pull"},{"id":"tags","level":"intermediate","topic":"History","title":"Tag a release"},{"id":"rebase","level":"advanced","topic":"Branches","title":"Rebase"},{"id":"stash","level":"advanced","topic":"Undo","title":"Stash work in progress"},{"id":"reset-revert","level":"advanced","topic":"Undo","title":"Reset vs revert"},{"id":"cherry-pick","level":"advanced","topic":"Branches","title":"Cherry-pick a commit"},{"id":"blame","level":"advanced","topic":"History","title":"Find who changed a line"},{"id":"amend","level":"advanced","topic":"Undo","title":"Fix the last commit"},{"id":"bisect","level":"brilliant","topic":"History","title":"Find a bug with bisect"},{"id":"reflog","level":"brilliant","topic":"Undo","title":"Recover lost commits with reflog"},{"id":"hooks","level":"brilliant","topic":"Automation","title":"Hooks"},{"id":"worktrees","level":"brilliant","topic":"Branches","title":"Worktrees"},{"id":"feature-workflow","level":"brilliant","topic":"Remotes","title":"Feature branch workflow"}],"examples":{"git":{"init-status":{"code":"# Make the folder a Git repository.\ngit init\n# status shows what Git sees. Nothing is tracked yet.\ngit status\n# Create a file. Git notices it but does not track it yet.\necho \"print('hello')\" > hello.py\ngit status","summary":"git init turns a folder into a repository. git status tells you what changed and what Git will do next.","notes":["git init makes a hidden .git folder that stores the whole history.","Untracked files exist in the folder but Git is not saving their history yet.","Run git status often. It also suggests the next command to run."],"pitfall":"Running git init in your home folder instead of the project folder makes Git track everything you own. Run it inside the project folder.","keywords":["git init","git status","repository","repo","untracked"],"stdin":"","output":"student@linux:~/project$ git init\nInitialized empty Git repository in /home/student/project/.git/\nstudent@linux:~/project$ git status\nOn branch main\n\nNo commits yet\n\nnothing to commit (create/copy files and use \"git add\" to track)\nstudent@linux:~/project$ echo \"print('hello')\" > hello.py\nstudent@linux:~/project$ git status\nOn branch main\n\nNo commits yet\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\t\u001b[31mhello.py\u001b[m\n\nnothing added to commit but untracked files present (use \"git add\" to track)","run":true,"shot":null,"shot_note":"","setup_note":"Starts in an empty folder named project.","preview_height":null,"mode":"session","filename":null},"add-commit":{"code":"# Both files are untracked. Nothing is saved in Git yet.\ngit status\n# git add stages a file. Staged files go into the next commit.\ngit add gradebook.py\ngit status\n# git commit saves everything staged as one snapshot, with a message.\ngit commit -m \"Add gradebook script\"\n# README.md was not staged, so it is not in that commit.\ngit status\n# git add . stages every new or changed file in this folder.\ngit add .\ngit commit -m \"Add README\"\n# Two commits, newest first.\ngit log --oneline","summary":"Saving work in Git takes two steps. git add picks the changes to save (staging), and git commit saves them as a snapshot with a message.","notes":["The staging area lets you commit some changes and leave others for a later commit.","git commit -m \"message\" sets the message on the command line. Write what the commit does, for example \"Add README\".","git add . means the current folder and everything in it. The dot is part of the command."],"pitfall":"Running git commit before git add gives \"nothing added to commit but untracked files present\". Stage the files first.","keywords":["git add","git commit","stage","staging area","commit message","-m","snapshot","save"],"stdin":"","output":"student@linux:~/project$ git status\nOn branch main\n\nNo commits yet\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\t\u001b[31mREADME.md\u001b[m\n\t\u001b[31mgradebook.py\u001b[m\n\nnothing added to commit but untracked files present (use \"git add\" to track)\nstudent@linux:~/project$ git add gradebook.py\nstudent@linux:~/project$ git status\nOn branch main\n\nNo commits yet\n\nChanges to be committed:\n  (use \"git rm --cached <file>...\" to unstage)\n\t\u001b[32mnew file:   gradebook.py\u001b[m\n\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\t\u001b[31mREADME.md\u001b[m\n\nstudent@linux:~/project$ git commit -m \"Add gradebook script\"\n[main (root-commit) 356cc16] Add gradebook script\n 1 file changed, 3 insertions(+)\n create mode 100644 gradebook.py\nstudent@linux:~/project$ git status\nOn branch main\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\t\u001b[31mREADME.md\u001b[m\n\nnothing added to commit but untracked files present (use \"git add\" to track)\nstudent@linux:~/project$ git add .\nstudent@linux:~/project$ git commit -m \"Add README\"\n[main dda46b7] Add README\n 1 file changed, 2 insertions(+)\n create mode 100644 README.md\nstudent@linux:~/project$ git log --oneline\n\u001b[33mdda46b7\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add README\n\u001b[33m356cc16\u001b[m Add gradebook script","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a new repository with two files Git does not track yet: gradebook.py and README.md.","preview_height":null,"mode":"session","filename":null},"log":{"code":"# git log lists every commit, newest first, with its author and date.\ngit log\n# --oneline shows one commit per line: a short hash and the message.\ngit log --oneline\n# -2 limits the list to the two newest commits.\ngit log --oneline -2\n# Put a file name after -- to see only the commits that changed that file.\ngit log --oneline -- scores.csv\n# -p shows the exact lines each commit changed. -1 shows only the newest commit.\ngit log -p -1","summary":"git log shows the history of the repository: who made each commit, when, and why. Options narrow the list or show the changes inside each commit.","notes":["Each commit has a hash, an ID of 40 letters and digits. The first 7 characters are enough to name a commit.","HEAD -> main in the log marks the commit you are on and the branch you are on.","git log -- scores.csv answers the question \"when did this file change?\""],"pitfall":"A long git log can fill the screen. Use --oneline or a number like -5 to keep it short.","keywords":["git log","history","--oneline","-p","commit hash","author","HEAD"],"stdin":"","output":"student@linux:~/project$ git log\n\u001b[33mcommit 6a9a7d22fb6bd8e84288343dab104af3b159f2fe\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:09:00 2026 -0500\n\n    Add Zoe's score\n\n\u001b[33mcommit ea51078329410bef2a0eb68bc7bf036d28c7029a\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:07:00 2026 -0500\n\n    Add quiz scores\n\n\u001b[33mcommit 2db5f93a564cc2c4e96d780d277c8791d40cab71\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:05:00 2026 -0500\n\n    Add README\n\n\u001b[33mcommit 93a2d4dcee9f2925a3503366d0abc933b7b2f1b1\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:03:00 2026 -0500\n\n    Add gradebook script\nstudent@linux:~/project$ git log --oneline\n\u001b[33m6a9a7d2\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add Zoe's score\n\u001b[33mea51078\u001b[m Add quiz scores\n\u001b[33m2db5f93\u001b[m Add README\n\u001b[33m93a2d4d\u001b[m Add gradebook script\nstudent@linux:~/project$ git log --oneline -2\n\u001b[33m6a9a7d2\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add Zoe's score\n\u001b[33mea51078\u001b[m Add quiz scores\nstudent@linux:~/project$ git log --oneline -- scores.csv\n\u001b[33m6a9a7d2\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add Zoe's score\n\u001b[33mea51078\u001b[m Add quiz scores\nstudent@linux:~/project$ git log -p -1\n\u001b[33mcommit 6a9a7d22fb6bd8e84288343dab104af3b159f2fe\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:09:00 2026 -0500\n\n    Add Zoe's score\n\n\u001b[1mdiff --git a/scores.csv b/scores.csv\u001b[m\n\u001b[1mindex e56ad1c..bdb4d85 100644\u001b[m\n\u001b[1m--- a/scores.csv\u001b[m\n\u001b[1m+++ b/scores.csv\u001b[m\n\u001b[36m@@ -2,3 +2,4 @@\u001b[m \u001b[mname,score\u001b[m\n Ava,88\u001b[m\n Liam,92\u001b[m\n Noah,79\u001b[m\n\u001b[32m+\u001b[m\u001b[32mZoe,95\u001b[m","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with four commits on main.","preview_height":null,"mode":"session","filename":null},"diff":{"code":"# Change Liam's score from 92 to 94.\nsed -i 's/Liam,92/Liam,94/' scores.csv\n# git diff shows changes you have not staged. - marks the old line and + marks the new line.\ngit diff\n# After git add, plain git diff shows nothing because no unstaged changes are left.\ngit add scores.csv\ngit diff\n# --staged shows what the next commit will contain.\ngit diff --staged\ngit commit -m \"Update Liam's score\"\n# Compare two commits: HEAD~1 is the commit before the newest one, HEAD.\ngit diff HEAD~1 HEAD","summary":"git diff shows the exact lines that changed. Use it before you commit to check what you are about to save.","notes":["git diff compares your files with the staging area. git diff --staged compares the staging area with the last commit.","Lines starting with - were removed and lines starting with + were added. A changed line shows up as one of each.","The @@ line gives line numbers: -1,5 +1,5 means the 5 lines starting at line 1, before and after the change."],"pitfall":"git diff prints nothing after you stage your changes, so it looks like nothing changed. Use git diff --staged to see staged changes.","keywords":["git diff","--staged","--cached","changes","compare","HEAD~1"],"stdin":"","output":"student@linux:~/project$ sed -i 's/Liam,92/Liam,94/' scores.csv\nstudent@linux:~/project$ git diff\n\u001b[1mdiff --git a/scores.csv b/scores.csv\u001b[m\n\u001b[1mindex bdb4d85..47185f1 100644\u001b[m\n\u001b[1m--- a/scores.csv\u001b[m\n\u001b[1m+++ b/scores.csv\u001b[m\n\u001b[36m@@ -1,5 +1,5 @@\u001b[m\n name,score\u001b[m\n Ava,88\u001b[m\n\u001b[31m-Liam,92\u001b[m\n\u001b[32m+\u001b[m\u001b[32mLiam,94\u001b[m\n Noah,79\u001b[m\n Zoe,95\u001b[m\nstudent@linux:~/project$ git add scores.csv\nstudent@linux:~/project$ git diff\nstudent@linux:~/project$ git diff --staged\n\u001b[1mdiff --git a/scores.csv b/scores.csv\u001b[m\n\u001b[1mindex bdb4d85..47185f1 100644\u001b[m\n\u001b[1m--- a/scores.csv\u001b[m\n\u001b[1m+++ b/scores.csv\u001b[m\n\u001b[36m@@ -1,5 +1,5 @@\u001b[m\n name,score\u001b[m\n Ava,88\u001b[m\n\u001b[31m-Liam,92\u001b[m\n\u001b[32m+\u001b[m\u001b[32mLiam,94\u001b[m\n Noah,79\u001b[m\n Zoe,95\u001b[m\nstudent@linux:~/project$ git commit -m \"Update Liam's score\"\n[main 0f41cdd] Update Liam's score\n 1 file changed, 1 insertion(+), 1 deletion(-)\nstudent@linux:~/project$ git diff HEAD~1 HEAD\n\u001b[1mdiff --git a/scores.csv b/scores.csv\u001b[m\n\u001b[1mindex bdb4d85..47185f1 100644\u001b[m\n\u001b[1m--- a/scores.csv\u001b[m\n\u001b[1m+++ b/scores.csv\u001b[m\n\u001b[36m@@ -1,5 +1,5 @@\u001b[m\n name,score\u001b[m\n Ava,88\u001b[m\n\u001b[31m-Liam,92\u001b[m\n\u001b[32m+\u001b[m\u001b[32mLiam,94\u001b[m\n Noah,79\u001b[m\n Zoe,95\u001b[m","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with one commit that has gradebook.py, README.md, and scores.csv.","preview_height":null,"mode":"session","filename":null},"gitignore":{"code":"# Python made a __pycache__ folder, and the program wrote debug.log. Neither belongs in the history.\ngit status\n# Each line of .gitignore is a pattern. A trailing / matches a folder. * matches any name.\nprintf '__pycache__/\\n*.log\\n' > .gitignore\ncat .gitignore\n# The ignored files no longer show up. .gitignore itself is a normal file to commit.\ngit status\ngit add .gitignore\ngit commit -m \"Ignore cache and log files\"\n# --ignored lists the files Git is skipping.\ngit status --ignored","summary":"A .gitignore file lists files and folders Git should not track, such as cache folders, logs, and passwords.","notes":["Commit .gitignore so everyone working on the project ignores the same files.","*.log ignores every file that ends in .log, in any folder.","Never commit passwords or API keys. Put them in a file that .gitignore lists."],"pitfall":".gitignore does not affect files Git already tracks. If you committed debug.log before, it keeps showing as modified. Run git rm --cached debug.log and commit to stop tracking it.","keywords":[".gitignore","ignore","__pycache__","*.log","untracked","git status --ignored"],"stdin":"","output":"student@linux:~/project$ git status\nOn branch main\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\t\u001b[31m__pycache__/\u001b[m\n\t\u001b[31mdebug.log\u001b[m\n\nnothing added to commit but untracked files present (use \"git add\" to track)\nstudent@linux:~/project$ printf '__pycache__/\\n*.log\\n' > .gitignore\nstudent@linux:~/project$ cat .gitignore\n__pycache__/\n*.log\nstudent@linux:~/project$ git status\nOn branch main\nUntracked files:\n  (use \"git add <file>...\" to include in what will be committed)\n\t\u001b[31m.gitignore\u001b[m\n\nnothing added to commit but untracked files present (use \"git add\" to track)\nstudent@linux:~/project$ git add .gitignore\nstudent@linux:~/project$ git commit -m \"Ignore cache and log files\"\n[main 9ca1582] Ignore cache and log files\n 1 file changed, 2 insertions(+)\n create mode 100644 .gitignore\nstudent@linux:~/project$ git status --ignored\nOn branch main\nIgnored files:\n  (use \"git add -f <file>...\" to include in what will be committed)\n\t\u001b[31m__pycache__/\u001b[m\n\t\u001b[31mdebug.log\u001b[m\n\nnothing to commit, working tree clean","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with one commit, plus two new untracked items: a __pycache__ folder and debug.log.","preview_height":null,"mode":"session","filename":null},"undo-working":{"code":"# Overwrite gradebook.py by mistake.\necho \"oops\" > gradebook.py\ncat gradebook.py\ngit status\n# git restore puts the file back to how it was in the last commit. The edit is gone for good.\ngit restore gradebook.py\ncat gradebook.py\n# Stage a change, then decide it should not be in the next commit.\necho 'Eli,84' >> scores.csv\ngit add scores.csv\ngit status\n# restore --staged unstages the file but keeps your edit in the file.\ngit restore --staged scores.csv\ngit status\n# Plain restore then throws the edit away.\ngit restore scores.csv\ngit status","summary":"git restore undoes changes you have not committed. Without options it resets a file to the last commit; with --staged it only unstages the file.","notes":["git restore file throws away your edits to that file. Git cannot get them back, because they were never committed.","git restore --staged file is the undo for git add. The file keeps your edits.","git status prints these commands for you under each section, so you do not have to remember them."],"pitfall":"git restore . resets every changed file in the folder at once. Check git status first so you do not lose work you meant to keep.","keywords":["git restore","--staged","undo","discard changes","unstage","git checkout --"],"stdin":"","output":"student@linux:~/project$ echo \"oops\" > gradebook.py\nstudent@linux:~/project$ cat gradebook.py\noops\nstudent@linux:~/project$ git status\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   gradebook.py\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ git restore gradebook.py\nstudent@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", average)\nstudent@linux:~/project$ echo 'Eli,84' >> scores.csv\nstudent@linux:~/project$ git add scores.csv\nstudent@linux:~/project$ git status\nOn branch main\nChanges to be committed:\n  (use \"git restore --staged <file>...\" to unstage)\n\t\u001b[32mmodified:   scores.csv\u001b[m\n\nstudent@linux:~/project$ git restore --staged scores.csv\nstudent@linux:~/project$ git status\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   scores.csv\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ git restore scores.csv\nstudent@linux:~/project$ git status\nOn branch main\nnothing to commit, working tree clean","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with one commit that has gradebook.py, README.md, and scores.csv.","preview_height":null,"mode":"session","filename":null},"branches":{"code":"# git branch lists branches. * marks the one you are on.\ngit branch\n# switch -c creates a new branch and moves to it.\ngit switch -c letter-grades\ngit branch\n# New commits go on the current branch only. -a stages every changed tracked file.\nprintf 'print(\"Letter:\", \"A\" if average >= 90 else \"B\")\\n' >> gradebook.py\ngit commit -am \"Print a letter grade\"\n# --graph --all draws every branch. main still points at the older commit.\ngit log --oneline --graph --all\n# Switching branches changes the files in the folder to match that branch.\ngit switch main\ncat gradebook.py\ngit switch letter-grades\ncat gradebook.py","summary":"A branch is a separate line of commits. You can try a change on a branch while main stays as it was.","notes":["A branch is a name that points at a commit. Each new commit moves the current branch forward.","git switch -c name creates and switches in one step. git switch name moves to a branch that already exists.","Older tutorials use git checkout -b name. It does the same thing as git switch -c name."],"pitfall":"Switching with uncommitted changes that conflict with the other branch fails with \"Your local changes ... would be overwritten\". Commit or stash first.","keywords":["git branch","git switch","-c","git checkout -b","branch","HEAD"],"stdin":"","output":"student@linux:~/project$ git branch\n* \u001b[32mmain\u001b[m\nstudent@linux:~/project$ git switch -c letter-grades\nSwitched to a new branch 'letter-grades'\nstudent@linux:~/project$ git branch\n* \u001b[32mletter-grades\u001b[m\n  main\u001b[m\nstudent@linux:~/project$ printf 'print(\"Letter:\", \"A\" if average >= 90 else \"B\")\\n' >> gradebook.py\nstudent@linux:~/project$ git commit -am \"Print a letter grade\"\n[letter-grades b88b6d4] Print a letter grade\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git log --oneline --graph --all\n* \u001b[33mb88b6d4\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print a letter grade\n* \u001b[33m263c8aa\u001b[m\u001b[33m (\u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add quiz scores\n* \u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ git switch main\nSwitched to branch 'main'\nstudent@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", average)\nstudent@linux:~/project$ git switch letter-grades\nSwitched to branch 'letter-grades'\nstudent@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", average)\nprint(\"Letter:\", \"A\" if average >= 90 else \"B\")","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with two commits on main.","preview_height":null,"mode":"session","filename":null},"merge":{"code":"# Two branches start from main. Neither one is merged yet.\ngit log --oneline --graph --all\n# git merge brings another branch into the branch you are on, so check that you are on main.\ngit branch\n# main has no commits of its own since readme-typo started, so Git just moves main forward (fast-forward).\ngit merge readme-typo\n# Now main and letter-grades each have a commit the other lacks, so Git makes a merge commit.\ngit merge --no-edit letter-grades\ngit log --oneline --graph --all\n# main now has both changes.\ncat README.md gradebook.py\n# Both branches are merged, so you can delete their names. The commits stay.\ngit branch -d readme-typo letter-grades\ngit log --oneline --graph --all","summary":"git merge combines the commits from another branch into the current branch. Switch to the branch that should receive the changes first.","notes":["A fast-forward happens when the current branch has no new commits. Git moves the branch name forward and makes no merge commit.","A merge commit has two parents. In the graph, it is where two lines join.","--no-edit accepts the default merge message instead of opening an editor."],"pitfall":"Merging while on the wrong branch merges in the wrong direction. Run git branch or git status before git merge.","keywords":["git merge","fast-forward","merge commit","--no-edit","git branch -d"],"stdin":"","output":"student@linux:~/project$ git log --oneline --graph --all\n* \u001b[33m671d966\u001b[m\u001b[33m (\u001b[m\u001b[1;32mreadme-typo\u001b[m\u001b[33m)\u001b[m Fix typo in README\n\u001b[31m|\u001b[m * \u001b[33m5ceb4a1\u001b[m\u001b[33m (\u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print a letter grade\n\u001b[31m|\u001b[m\u001b[31m/\u001b[m  \n* \u001b[33m5b1773b\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script\nstudent@linux:~/project$ git branch\n  letter-grades\u001b[m\n* \u001b[32mmain\u001b[m\n  readme-typo\u001b[m\nstudent@linux:~/project$ git merge readme-typo\nUpdating 5b1773b..671d966\nFast-forward\n README.md | 2 \u001b[32m+\u001b[m\u001b[31m-\u001b[m\n 1 file changed, 1 insertion(+), 1 deletion(-)\nstudent@linux:~/project$ git merge --no-edit letter-grades\nMerge made by the 'ort' strategy.\n gradebook.py | 1 \u001b[32m+\u001b[m\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git log --oneline --graph --all\n*   \u001b[33m9e0d924\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Merge branch 'letter-grades'\n\u001b[31m|\u001b[m\u001b[32m\\\u001b[m  \n\u001b[31m|\u001b[m * \u001b[33m5ceb4a1\u001b[m\u001b[33m (\u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print a letter grade\n* \u001b[32m|\u001b[m \u001b[33m671d966\u001b[m\u001b[33m (\u001b[m\u001b[1;32mreadme-typo\u001b[m\u001b[33m)\u001b[m Fix typo in README\n\u001b[32m|\u001b[m\u001b[32m/\u001b[m  \n* \u001b[33m5b1773b\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script\nstudent@linux:~/project$ cat README.md gradebook.py\n# Gradebook\nQuiz scores for Period 3.\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", average)\nprint(\"Letter:\", \"A\" if average >= 90 else \"B\")\nstudent@linux:~/project$ git branch -d readme-typo letter-grades\nDeleted branch readme-typo (was 671d966).\nDeleted branch letter-grades (was 5ceb4a1).\nstudent@linux:~/project$ git log --oneline --graph --all\n*   \u001b[33m9e0d924\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Merge branch 'letter-grades'\n\u001b[31m|\u001b[m\u001b[32m\\\u001b[m  \n\u001b[31m|\u001b[m * \u001b[33m5ceb4a1\u001b[m Print a letter grade\n* \u001b[32m|\u001b[m \u001b[33m671d966\u001b[m Fix typo in README\n\u001b[32m|\u001b[m\u001b[32m/\u001b[m  \n* \u001b[33m5b1773b\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script","run":true,"shot":null,"shot_note":"","setup_note":"Starts on main with two commits. Two branches start from main: letter-grades (a change to gradebook.py) and readme-typo (a fix to README.md).","preview_height":null,"mode":"session","filename":null},"merge-conflict":{"code":"# Both branches changed Liam's line in scores.csv.\ngit log --oneline --graph --all\n# Git cannot choose between the two versions, so the merge stops with a conflict.\ngit merge retake-scores\ngit status\n# Git wrote both versions into the file between conflict markers.\ncat scores.csv\n# Keep the retake score. Rewrite the file with no markers.\nprintf 'name,score\\nAva,88\\nLiam,97\\nNoah,79\\nZoe,95\\n' > scores.csv\ncat scores.csv\n# Staging the file tells Git the conflict is resolved. The commit finishes the merge.\ngit add scores.csv\ngit commit -m \"Merge retake scores\"\ngit log --oneline --graph --all","summary":"A merge conflict happens when two branches change the same lines. Git stops, marks both versions in the file, and waits for you to choose.","notes":["Between <<<<<<< HEAD and ======= is your branch's version. Between ======= and >>>>>>> is the other branch's version.","Delete all three marker lines and leave the text you want. In an editor, this is the same edit done by hand.","git merge --abort cancels the merge and puts everything back the way it was before."],"pitfall":"Committing a file that still has <<<<<<< in it saves the markers into your code, and Python reports SyntaxError. Run cat or git diff to check before git add.","keywords":["merge conflict","CONFLICT","<<<<<<<","=======",">>>>>>>","git merge --abort","resolve"],"stdin":"","output":"student@linux:~/project$ git log --oneline --graph --all\n* \u001b[33m83c60e4\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Fix Liam's score\n\u001b[31m|\u001b[m * \u001b[33m5dd16b6\u001b[m\u001b[33m (\u001b[m\u001b[1;32mretake-scores\u001b[m\u001b[33m)\u001b[m Record Liam's retake score\n\u001b[31m|\u001b[m\u001b[31m/\u001b[m  \n* \u001b[33m74d3d39\u001b[m Add quiz scores\nstudent@linux:~/project$ git merge retake-scores\nAuto-merging scores.csv\nCONFLICT (content): Merge conflict in scores.csv\nAutomatic merge failed; fix conflicts and then commit the result.\nstudent@linux:~/project$ git status\nOn branch main\nYou have unmerged paths.\n  (fix conflicts and run \"git commit\")\n  (use \"git merge --abort\" to abort the merge)\n\nUnmerged paths:\n  (use \"git add <file>...\" to mark resolution)\n\t\u001b[31mboth modified:   scores.csv\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ cat scores.csv\nname,score\nAva,88\n<<<<<<< HEAD\nLiam,94\n=======\nLiam,97\n>>>>>>> retake-scores\nNoah,79\nZoe,95\nstudent@linux:~/project$ printf 'name,score\\nAva,88\\nLiam,97\\nNoah,79\\nZoe,95\\n' > scores.csv\nstudent@linux:~/project$ cat scores.csv\nname,score\nAva,88\nLiam,97\nNoah,79\nZoe,95\nstudent@linux:~/project$ git add scores.csv\nstudent@linux:~/project$ git commit -m \"Merge retake scores\"\n[main c293283] Merge retake scores\nstudent@linux:~/project$ git log --oneline --graph --all\n*   \u001b[33mc293283\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Merge retake scores\n\u001b[31m|\u001b[m\u001b[32m\\\u001b[m  \n\u001b[31m|\u001b[m * \u001b[33m5dd16b6\u001b[m\u001b[33m (\u001b[m\u001b[1;32mretake-scores\u001b[m\u001b[33m)\u001b[m Record Liam's retake score\n* \u001b[32m|\u001b[m \u001b[33m83c60e4\u001b[m Fix Liam's score\n\u001b[32m|\u001b[m\u001b[32m/\u001b[m  \n* \u001b[33m74d3d39\u001b[m Add quiz scores","run":true,"shot":null,"shot_note":"","setup_note":"Starts on main. main changed Liam's score to 94, and the branch retake-scores changed the same line to 97.","preview_height":null,"mode":"session","filename":null},"clone-remote":{"code":"# git clone copies a repository and its whole history into a new folder.\ngit clone ~/gradebook.git\ncd gradebook\nls\ngit log --oneline\n# The clone remembers where it came from under the name origin.\ngit remote -v\n# -a also lists remote-tracking branches. origin/main is your copy of main on origin.\ngit branch -a\ngit status\n# Add a second remote and push to it. This is how you connect a project to a new GitHub repository.\ngit remote add backup ~/backup.git\ngit remote -v\ngit push --no-progress backup main","summary":"A remote is another copy of the repository, usually on GitHub. git clone downloads one, and git remote lists and adds the names you use to reach them.","notes":["Here the remotes are folders on the same computer. With GitHub the URL looks like https://github.com/maya/gradebook.git, and the commands are the same.","origin is only a default name. git remote add gives any URL a name you choose.","A .git ending marks a bare repository: it stores history but has no working files, like the copy on GitHub."],"pitfall":"Running git clone inside another repository puts one repository inside the other. cd to the folder where you keep projects first.","keywords":["git clone","git remote","origin","remote -v","git remote add","github","bare repository"],"stdin":"","output":"student@linux:~/project$ git clone ~/gradebook.git\nCloning into 'gradebook'...\ndone.\nstudent@linux:~/project$ cd gradebook\nstudent@linux:~/project/gradebook$ ls\nREADME.md  gradebook.py  scores.csv\nstudent@linux:~/project/gradebook$ git log --oneline\n\u001b[33m99d8028\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m, \u001b[m\u001b[1;31morigin/main\u001b[m\u001b[33m, \u001b[m\u001b[1;31morigin/HEAD\u001b[m\u001b[33m)\u001b[m Add quiz scores\n\u001b[33m610f512\u001b[m Add gradebook script\nstudent@linux:~/project/gradebook$ git remote -v\norigin\t/home/student/gradebook.git (fetch)\norigin\t/home/student/gradebook.git (push)\nstudent@linux:~/project/gradebook$ git branch -a\n* \u001b[32mmain\u001b[m\n  \u001b[31mremotes/origin/HEAD\u001b[m -> origin/main\n  \u001b[31mremotes/origin/main\u001b[m\nstudent@linux:~/project/gradebook$ git status\nOn branch main\nYour branch is up to date with 'origin/main'.\n\nnothing to commit, working tree clean\nstudent@linux:~/project/gradebook$ git remote add backup ~/backup.git\nstudent@linux:~/project/gradebook$ git remote -v\nbackup\t/home/student/backup.git (fetch)\nbackup\t/home/student/backup.git (push)\norigin\t/home/student/gradebook.git (fetch)\norigin\t/home/student/gradebook.git (push)\nstudent@linux:~/project/gradebook$ git push --no-progress backup main\nTo /home/student/backup.git\n * [new branch]      main -> main","run":true,"shot":null,"shot_note":"","setup_note":"Starts in an empty folder. ../gradebook.git is the class repository with two commits, and ../backup.git is an empty repository.","preview_height":null,"mode":"session","filename":null},"push-pull":{"code":"# Maya adds a score and commits. The commit is only on her computer so far.\necho 'Eli,84' >> scores.csv\ngit commit -am \"Add Eli's score\"\n# status compares with origin/main as of the last download, so it does not know about Jordan's push.\ngit status\n# git push sends your commits to origin. It is rejected because origin has a commit you do not have.\ngit push\n# git pull downloads the new commits (fetch) and merges them into your branch. --no-progress hides the transfer counters.\ngit pull --no-progress --no-edit\ngit log --oneline --graph --all\n# Now your branch includes everything on origin, so the push works.\ngit push --no-progress\ngit status","summary":"git push uploads your commits to a remote. git pull downloads commits other people pushed and merges them into your branch.","notes":["git pull is git fetch followed by git merge. git fetch alone downloads without changing your files.","\"Your branch is up to date\" only means up to date with the last fetch. Run git pull to check for new work.","The pull made a merge commit because both Maya and Jordan had new commits."],"pitfall":"git push fails with \"rejected ... (fetch first)\" when someone pushed before you. Run git pull, fix any conflicts, then push again.","keywords":["git push","git pull","git fetch","rejected","fetch first","origin","upstream"],"stdin":"","output":"student@linux:~/project$ echo 'Eli,84' >> scores.csv\nstudent@linux:~/project$ git commit -am \"Add Eli's score\"\n[main 96ab586] Add Eli's score\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git status\nOn branch main\nYour branch is ahead of 'origin/main' by 1 commit.\n  (use \"git push\" to publish your local commits)\n\nnothing to commit, working tree clean\nstudent@linux:~/project$ git push\nTo /home/student/gradebook.git\n ! [rejected]        main -> main (fetch first)\nerror: failed to push some refs to '/home/student/gradebook.git'\nhint: Updates were rejected because the remote contains work that you do not\nhint: have locally. This is usually caused by another repository pushing to\nhint: the same ref. If you want to integrate the remote changes, use\nhint: 'git pull' before pushing again.\nhint: See the 'Note about fast-forwards' in 'git push --help' for details.\nstudent@linux:~/project$ git pull --no-progress --no-edit\nFrom /home/student/gradebook\n   99d8028..6c872a3  main       -> origin/main\nMerge made by the 'ort' strategy.\n README.md | 2 \u001b[32m++\u001b[m\n 1 file changed, 2 insertions(+)\nstudent@linux:~/project$ git log --oneline --graph --all\n*   \u001b[33md274f17\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Merge branch 'main' of /home/student/gradebook\n\u001b[31m|\u001b[m\u001b[32m\\\u001b[m  \n\u001b[31m|\u001b[m * \u001b[33m6c872a3\u001b[m\u001b[33m (\u001b[m\u001b[1;31morigin/main\u001b[m\u001b[33m, \u001b[m\u001b[1;31morigin/HEAD\u001b[m\u001b[33m)\u001b[m Add how to run\n* \u001b[32m|\u001b[m \u001b[33m96ab586\u001b[m Add Eli's score\n\u001b[32m|\u001b[m\u001b[32m/\u001b[m  \n* \u001b[33m99d8028\u001b[m Add quiz scores\n* \u001b[33m610f512\u001b[m Add gradebook script\nstudent@linux:~/project$ git push --no-progress\nTo /home/student/gradebook.git\n   6c872a3..d274f17  main -> main\nstudent@linux:~/project$ git status\nOn branch main\nYour branch is up to date with 'origin/main'.\n\nnothing to commit, working tree clean","run":true,"shot":null,"shot_note":"","setup_note":"Starts in Maya's clone of ../gradebook.git. Her teammate Jordan has his own clone in ../jordan and already pushed a commit Maya does not have.","preview_height":null,"mode":"session","filename":null},"tags":{"code":"# No tags yet.\ngit tag\n# An annotated tag (-a) stores a message, who made the tag, and when.\ngit tag -a v1.0 -m \"Version turned in for Unit 1\"\n# The tag shows next to its commit in the log.\ngit log --oneline\n# git show displays the tag details and the commit it points to.\ngit show --no-patch v1.0\n# Tag an older commit by naming it. HEAD~1 is the commit before the newest one.\ngit tag -a v0.9 -m \"Draft for peer review\" HEAD~1\ngit tag\ngit log --oneline","summary":"A tag is a permanent name for one commit, such as v1.0. Use tags to mark versions you turned in or released.","notes":["Unlike a branch, a tag does not move when you make new commits.","git push does not send tags. Use git push origin v1.0 for one tag or git push --tags for all of them.","git switch --detach v1.0 lets you look at the files as they were in that version."],"pitfall":"git tag v1.0 without -a makes a lightweight tag with no message or date. Use -a and -m for versions you want to describe.","keywords":["git tag","-a","annotated tag","release","version","v1.0","git push --tags"],"stdin":"","output":"student@linux:~/project$ git tag\nstudent@linux:~/project$ git tag -a v1.0 -m \"Version turned in for Unit 1\"\nstudent@linux:~/project$ git log --oneline\n\u001b[33md4e2193\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m, \u001b[m\u001b[1;33mtag: \u001b[m\u001b[1;33mv1.0\u001b[m\u001b[33m)\u001b[m Print the highest score\n\u001b[33m263c8aa\u001b[m Add quiz scores\n\u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ git show --no-patch v1.0\n\u001b[33mtag v1.0\u001b[m\nTagger: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:10:00 2026 -0500\n\nVersion turned in for Unit 1\n\n\u001b[33mcommit d4e2193cad01b133f77754e0511a77319442aa42\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m, \u001b[m\u001b[1;33mtag: \u001b[m\u001b[1;33mv1.0\u001b[m\u001b[33m)\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:08:00 2026 -0500\n\n    Print the highest score\nstudent@linux:~/project$ git tag -a v0.9 -m \"Draft for peer review\" HEAD~1\nstudent@linux:~/project$ git tag\nv0.9\nv1.0\nstudent@linux:~/project$ git log --oneline\n\u001b[33md4e2193\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m, \u001b[m\u001b[1;33mtag: \u001b[m\u001b[1;33mv1.0\u001b[m\u001b[33m)\u001b[m Print the highest score\n\u001b[33m263c8aa\u001b[m\u001b[33m (\u001b[m\u001b[1;33mtag: \u001b[m\u001b[1;33mv0.9\u001b[m\u001b[33m)\u001b[m Add quiz scores\n\u001b[33m5cbfaad\u001b[m Add gradebook script","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with three commits on main.","preview_height":null,"mode":"session","filename":null},"rebase":{"code":"# letter-grades started before main got \"Fix typo in README\".\ngit log --oneline --graph --all\n# Rebase replays the branch's commits on top of the newest main.\ngit switch letter-grades\ngit rebase main\n# The history is one straight line now. The two branch commits got new hashes.\ngit log --oneline --graph --all\n# main can fast-forward, so no merge commit is needed.\ngit switch main\ngit merge letter-grades\ngit log --oneline --graph","summary":"git rebase moves your branch so it starts from the newest commit of another branch. The result is a straight history with no merge commit.","notes":["Rebase copies each commit onto the new base, so every copied commit gets a new hash.","If a replayed commit conflicts, fix the file, git add it, and run git rebase --continue. git rebase --abort cancels.","Merge keeps the history exactly as it happened. Rebase rewrites it to look like you started later. Both end with the same files."],"pitfall":"Do not rebase commits you already pushed and others pulled. Their copies have the old hashes, and the next pull mixes both versions. Rebase only local work.","keywords":["git rebase","rebase","linear history","--continue","--abort","replay"],"stdin":"","output":"student@linux:~/project$ git log --oneline --graph --all\n* \u001b[33mb1b88ee\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Fix typo in README\n\u001b[31m|\u001b[m * \u001b[33mda7f80a\u001b[m\u001b[33m (\u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print the letter grade\n\u001b[31m|\u001b[m * \u001b[33mb6d6297\u001b[m Add letter grade function\n\u001b[31m|\u001b[m\u001b[31m/\u001b[m  \n* \u001b[33m5b1773b\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script\nstudent@linux:~/project$ git switch letter-grades\nSwitched to branch 'letter-grades'\nstudent@linux:~/project$ git rebase main\nRebasing (1/2)\nRebasing (2/2)\n\n                                                                                \nSuccessfully rebased and updated refs/heads/letter-grades.\nstudent@linux:~/project$ git log --oneline --graph --all\n* \u001b[33m273d60f\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print the letter grade\n* \u001b[33m1290b24\u001b[m Add letter grade function\n* \u001b[33mb1b88ee\u001b[m\u001b[33m (\u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Fix typo in README\n* \u001b[33m5b1773b\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script\nstudent@linux:~/project$ git switch main\nSwitched to branch 'main'\nstudent@linux:~/project$ git merge letter-grades\nUpdating b1b88ee..273d60f\nFast-forward\n gradebook.py | 3 \u001b[32m+++\u001b[m\n 1 file changed, 3 insertions(+)\nstudent@linux:~/project$ git log --oneline --graph\n* \u001b[33m273d60f\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m, \u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print the letter grade\n* \u001b[33m1290b24\u001b[m Add letter grade function\n* \u001b[33mb1b88ee\u001b[m Fix typo in README\n* \u001b[33m5b1773b\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script","run":true,"shot":null,"shot_note":"","setup_note":"Starts on main. The branch letter-grades has two commits, and main got one more commit after the branch started.","preview_height":null,"mode":"session","filename":null},"stash":{"code":"# Maya is in the middle of a change when she notices a typo she wants to fix first.\nprintf 'print(\"Highest:\", max(scores))\\n' >> gradebook.py\ngit status\n# git stash saves your uncommitted changes and gives you a clean folder.\ngit stash push -m \"highest score in progress\"\ngit status\ngit stash list\n# Make the quick fix and commit it on its own.\nsed -i 's/socres/scores/' README.md\ngit commit -am \"Fix typo in README\"\n# pop puts the stashed changes back and removes them from the stash list.\ngit stash pop\ngit status\ngit stash list","summary":"git stash sets uncommitted changes aside so you can switch tasks with a clean folder, then brings them back later.","notes":["-m gives the stash a name you can read in git stash list.","git stash pop applies the newest stash and deletes it. git stash apply applies it and keeps it in the list.","Stashes are local. They are not pushed and they are easy to forget, so pop them soon."],"pitfall":"git stash skips untracked (new) files, so a new file stays in the folder. Use git stash -u to include them.","keywords":["git stash","stash pop","stash list","stash apply","-u","work in progress","save changes"],"stdin":"","output":"student@linux:~/project$ printf 'print(\"Highest:\", max(scores))\\n' >> gradebook.py\nstudent@linux:~/project$ git status\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   gradebook.py\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ git stash push -m \"highest score in progress\"\nSaved working directory and index state On main: highest score in progress\nstudent@linux:~/project$ git status\nOn branch main\nnothing to commit, working tree clean\nstudent@linux:~/project$ git stash list\nstash@{0}: On main: highest score in progress\nstudent@linux:~/project$ sed -i 's/socres/scores/' README.md\nstudent@linux:~/project$ git commit -am \"Fix typo in README\"\n[main 671d966] Fix typo in README\n 1 file changed, 1 insertion(+), 1 deletion(-)\nstudent@linux:~/project$ git stash pop\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   gradebook.py\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nDropped refs/stash@{0} (9bdb2bf536ad9001a078bb07204ba09a6d7977aa)\nstudent@linux:~/project$ git status\nOn branch main\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   gradebook.py\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ git stash list","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with two commits on main. README.md has a typo.","preview_height":null,"mode":"session","filename":null},"reset-revert":{"code":"# The last two commits need to be undone.\ngit log --oneline\n# \"Add debug print\" was never pushed. reset moves main back one commit, and --hard also resets the files.\ngit reset --hard HEAD~1\n# That commit is gone from the log.\ngit log --oneline\n# \"Drop the lowest score\" was already pushed. revert adds a new commit that undoes it, so shared history does not change.\ngit revert --no-edit HEAD\n# The commit and its undo both stay in the log.\ngit log --oneline\ncat gradebook.py","summary":"git reset moves a branch back to an older commit and drops the newer ones. git revert keeps history and adds a new commit that undoes an old one.","notes":["Use reset only on commits you have not pushed. Use revert on commits other people already have.","reset --hard also resets your files. reset --soft keeps the changes staged, and plain reset keeps them unstaged.","git revert can undo any commit, not only the newest. Name it with its hash."],"pitfall":"git reset --hard deletes uncommitted changes with no undo. Run git status first, and commit or stash anything you want to keep.","keywords":["git reset","git revert","--hard","--soft","undo commit","HEAD~1","rewrite history"],"stdin":"","output":"student@linux:~/project$ git log --oneline\n\u001b[33m95069ec\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add debug print\n\u001b[33md03ed8f\u001b[m Drop the lowest score\n\u001b[33m2db5f93\u001b[m Add README\n\u001b[33m93a2d4d\u001b[m Add gradebook script\nstudent@linux:~/project$ git reset --hard HEAD~1\nHEAD is now at d03ed8f Drop the lowest score\nstudent@linux:~/project$ git log --oneline\n\u001b[33md03ed8f\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Drop the lowest score\n\u001b[33m2db5f93\u001b[m Add README\n\u001b[33m93a2d4d\u001b[m Add gradebook script\nstudent@linux:~/project$ git revert --no-edit HEAD\n[main 8b6644c] Revert \"Drop the lowest score\"\n Date: Tue Sep 8 09:13:00 2026 -0500\n 1 file changed, 1 deletion(-)\nstudent@linux:~/project$ git log --oneline\n\u001b[33m8b6644c\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Revert \"Drop the lowest score\"\n\u001b[33md03ed8f\u001b[m Drop the lowest score\n\u001b[33m2db5f93\u001b[m Add README\n\u001b[33m93a2d4d\u001b[m Add gradebook script\nstudent@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", average)","run":true,"shot":null,"shot_note":"","setup_note":"Starts with four commits on main. The first three were already pushed and the team has them. The newest commit, \"Add debug print\", was never pushed.","preview_height":null,"mode":"session","filename":null},"cherry-pick":{"code":"# main needs the fix from experiment, but not the chart work.\ngit log --oneline --graph --all\n# Copy that one commit onto main by its hash.\ngit cherry-pick 66e60d2\ngit log --oneline --graph --all\n# main has the fix. chart.py stayed on experiment.\ncat gradebook.py\nls","summary":"git cherry-pick copies one commit from another branch onto the current branch, without merging the rest of that branch.","notes":["The copy is a new commit with the same message and changes but a different hash.","Find the hash with git log --oneline --all. The first 7 characters are enough.","If the experiment branch is merged later, Git sees the same change twice and usually handles it without a conflict."],"pitfall":"Cherry-picking a commit that depends on an earlier commit (for example a change to chart.py) fails with a conflict or a missing file. Pick commits that stand alone.","keywords":["git cherry-pick","copy commit","hotfix","hash","apply one commit"],"stdin":"","output":"student@linux:~/project$ git log --oneline --graph --all\n* \u001b[33medc1aee\u001b[m\u001b[33m (\u001b[m\u001b[1;32mexperiment\u001b[m\u001b[33m)\u001b[m Label the chart\n* \u001b[33m66e60d2\u001b[m Fix average for an empty list\n* \u001b[33m21a5943\u001b[m Try a bar chart\n* \u001b[33m263c8aa\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add quiz scores\n* \u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ git cherry-pick 66e60d2\n[main da929cf] Fix average for an empty list\n Date: Tue Sep 8 09:11:00 2026 -0500\n 1 file changed, 1 insertion(+), 1 deletion(-)\nstudent@linux:~/project$ git log --oneline --graph --all\n* \u001b[33mda929cf\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Fix average for an empty list\n\u001b[31m|\u001b[m * \u001b[33medc1aee\u001b[m\u001b[33m (\u001b[m\u001b[1;32mexperiment\u001b[m\u001b[33m)\u001b[m Label the chart\n\u001b[31m|\u001b[m * \u001b[33m66e60d2\u001b[m Fix average for an empty list\n\u001b[31m|\u001b[m * \u001b[33m21a5943\u001b[m Try a bar chart\n\u001b[31m|\u001b[m\u001b[31m/\u001b[m  \n* \u001b[33m263c8aa\u001b[m Add quiz scores\n* \u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores) if scores else 0\nprint(\"Average:\", average)\nstudent@linux:~/project$ ls\nREADME.md  gradebook.py  scores.csv","run":true,"shot":null,"shot_note":"","setup_note":"Starts on main. The branch experiment has three commits, and only the middle one, \"Fix average for an empty list\", belongs on main.","preview_height":null,"mode":"session","filename":null},"blame":{"code":"# Line 3 rounds the average. Who changed it, and why?\ncat gradebook.py\n# blame shows, for each line, the commit, author, and date of its last change.\ngit blame gradebook.py\n# -L 3,3 shows only line 3.\ngit blame -L 3,3 gradebook.py\n# Look up the commit blame named to read its message and the full change.\ngit show 4a4b43c","summary":"git blame shows who last changed each line of a file and in which commit. Use it to find the commit that explains a line.","notes":["Each line starts with a short commit hash. Pass it to git show to see the whole commit.","blame shows the last change only. If a line was edited twice, git log -L 3,3:gradebook.py shows every version.","A ^ before a hash marks the first commit in the history. Lines you have not committed yet show 00000000 and Not Committed Yet."],"pitfall":"The author in blame is whoever made the commit, which is not always who wrote the idea. Read the commit message before you blame a teammate.","keywords":["git blame","-L","who changed","author","line history","git show"],"stdin":"","output":"student@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95, 84]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", round(average, 1))\nstudent@linux:~/project$ git blame gradebook.py\n8027c961 (Maya Lopez 2026-09-08 09:08:00 -0500 1) scores = [88, 92, 79, 95, 84]\n^ea1f863 (Maya Lopez 2026-09-08 09:04:00 -0500 2) average = sum(scores) / len(scores)\n4a4b43c4 (Jordan Kim 2026-09-08 09:06:00 -0500 3) print(\"Average:\", round(average, 1))\nstudent@linux:~/project$ git blame -L 3,3 gradebook.py\n4a4b43c4 (Jordan Kim 2026-09-08 09:06:00 -0500 3) print(\"Average:\", round(average, 1))\nstudent@linux:~/project$ git show 4a4b43c\n\u001b[33mcommit 4a4b43c46a735969ebc0bf286c3aec604ef540fc\u001b[m\nAuthor: Jordan Kim <jordan@example.com>\nDate:   Tue Sep 8 09:06:00 2026 -0500\n\n    Round the average to one decimal\n\n\u001b[1mdiff --git a/gradebook.py b/gradebook.py\u001b[m\n\u001b[1mindex 94bdaa4..e8d1cb1 100644\u001b[m\n\u001b[1m--- a/gradebook.py\u001b[m\n\u001b[1m+++ b/gradebook.py\u001b[m\n\u001b[36m@@ -1,3 +1,3 @@\u001b[m\n scores = [88, 92, 79, 95]\u001b[m\n average = sum(scores) / len(scores)\u001b[m\n\u001b[31m-print(\"Average:\", average)\u001b[m\n\u001b[32m+\u001b[m\u001b[32mprint(\"Average:\", round(average, 1))\u001b[m","run":true,"shot":null,"shot_note":"","setup_note":"Starts with three commits on main. Maya Lopez made the first and last ones. Her teammate Jordan Kim made the middle one.","preview_height":null,"mode":"session","filename":null},"amend":{"code":"# Commit a new score with a typo in the message.\necho 'Eli,84' >> scores.csv\ngit commit -am \"Add Elis score\"\ngit log --oneline\n# --amend replaces the last commit. -m gives it a new message.\ngit commit --amend -m \"Add Eli's score\"\ngit log --oneline\n# Forgot a file? Stage it and amend again. --no-edit keeps the message.\necho 'Class size: 5' >> README.md\ngit add README.md\ngit commit --amend --no-edit\n# Still one commit, now with both files. Its hash changed again.\ngit log --oneline --stat -1","summary":"git commit --amend replaces the most recent commit. Use it to fix the message or add a file you forgot.","notes":["Amend makes a new commit with a new hash. The old one is no longer on the branch.","--no-edit keeps the existing message. -m sets a new one.","To change an older commit, make a new commit that fixes it, or use git revert."],"pitfall":"Amending a commit you already pushed makes git push fail with \"rejected (non-fast-forward)\". Only amend commits that are still local.","keywords":["git commit --amend","amend","fix commit message","--no-edit","forgot file"],"stdin":"","output":"student@linux:~/project$ echo 'Eli,84' >> scores.csv\nstudent@linux:~/project$ git commit -am \"Add Elis score\"\n[main 9cc53d9] Add Elis score\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git log --oneline\n\u001b[33m9cc53d9\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add Elis score\n\u001b[33m1e91553\u001b[m Start gradebook\nstudent@linux:~/project$ git commit --amend -m \"Add Eli's score\"\n[main 4b1ada1] Add Eli's score\n Date: Tue Sep 8 09:07:00 2026 -0500\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git log --oneline\n\u001b[33m4b1ada1\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add Eli's score\n\u001b[33m1e91553\u001b[m Start gradebook\nstudent@linux:~/project$ echo 'Class size: 5' >> README.md\nstudent@linux:~/project$ git add README.md\nstudent@linux:~/project$ git commit --amend --no-edit\n[main 7a0de71] Add Eli's score\n Date: Tue Sep 8 09:07:00 2026 -0500\n 2 files changed, 2 insertions(+)\nstudent@linux:~/project$ git log --oneline --stat -1\n\u001b[33m7a0de71\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add Eli's score\n README.md  | 1 \u001b[32m+\u001b[m\n scores.csv | 1 \u001b[32m+\u001b[m\n 2 files changed, 2 insertions(+)","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with one commit that has gradebook.py, README.md, and scores.csv.","preview_height":null,"mode":"session","filename":null},"bisect":{"code":"# The test passed in the first commit and fails now. Six commits came after it.\npython3 test_gradebook.py\ngit log --oneline\n# Start bisect: the newest commit is bad and the first commit (HEAD~6) is good.\ngit bisect start HEAD HEAD~6\n# bisect run checks out commits and runs the test. Exit code 0 means good, 1 means bad.\ngit bisect run python3 test_gradebook.py\n# Go back to where you started.\ngit bisect reset","summary":"git bisect finds the commit that introduced a bug with a binary search. With git bisect run, a test script marks each commit good or bad for you.","notes":["Bisect halves the range every step. It checked 3 commits here and needs about 10 for 1,000 commits.","The test command must exit with 0 for good and 1 for bad. exit(1) in Python does that.","Without run, mark commits by hand with git bisect good and git bisect bad, then git bisect reset."],"pitfall":"Forgetting git bisect reset leaves you on an old commit with no branch (detached HEAD). New commits made there are easy to lose.","keywords":["git bisect","bisect run","binary search","find bug","first bad commit","regression"],"stdin":"","output":"student@linux:~/project$ python3 test_gradebook.py\nFAIL: average([80, 90]) is 45.0\nstudent@linux:~/project$ git log --oneline\n\u001b[33mb3f86f4\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Explain how to run the test\n\u001b[33m8631b3e\u001b[m Add highest score function\n\u001b[33me43da38\u001b[m Skip the header row\n\u001b[33m717842b\u001b[m Add quiz scores\n\u001b[33m37d5008\u001b[m Add letter grade function\n\u001b[33m90c0074\u001b[m Add README\n\u001b[33m0630d9f\u001b[m Add average and its test\nstudent@linux:~/project$ git bisect start HEAD HEAD~6\nBisecting: 2 revisions left to test after this (roughly 2 steps)\n[717842b16fe222c8668c8128c221f04a0f19aaaa] Add quiz scores\nstudent@linux:~/project$ git bisect run python3 test_gradebook.py\nrunning 'python3' 'test_gradebook.py'\nPASS\nBisecting: 0 revisions left to test after this (roughly 1 step)\n[8631b3e9f5ec7bc58cba612ebd0833fea37e8b13] Add highest score function\nrunning 'python3' 'test_gradebook.py'\nFAIL: average([80, 90]) is 45.0\nBisecting: 0 revisions left to test after this (roughly 0 steps)\n[e43da38e82d2064aa44173445c3ad183b9937155] Skip the header row\nrunning 'python3' 'test_gradebook.py'\nFAIL: average([80, 90]) is 45.0\ne43da38e82d2064aa44173445c3ad183b9937155 is the first bad commit\n\u001b[33mcommit e43da38e82d2064aa44173445c3ad183b9937155\u001b[m\nAuthor: Maya Lopez <maya@example.com>\nDate:   Tue Sep 8 09:13:00 2026 -0500\n\n    Skip the header row\n\n gradebook.py | 2 \u001b[32m+\u001b[m\u001b[31m-\u001b[m\n 1 file changed, 1 insertion(+), 1 deletion(-)\nbisect found first bad commit\nstudent@linux:~/project$ git bisect reset\nPrevious HEAD position was e43da38 Skip the header row\nSwitched to branch 'main'","run":true,"shot":null,"shot_note":"","setup_note":"Starts with seven commits on main. test_gradebook.py checks that average([80, 90]) is 85. It passed in the first commit and fails now.","preview_height":null,"mode":"session","filename":null},"reflog":{"code":"# Three commits on main.\ngit log --oneline\n# reset --hard HEAD~1 moves main back one commit. \"Print a letter grade\" is no longer in the log.\ngit reset --hard HEAD~1\ngit log --oneline\n# The reflog lists every commit HEAD has pointed to, including the one that was dropped.\ngit reflog\n# HEAD@{1} is where HEAD was one step ago, before the reset. Reset back to it.\ngit reset --hard HEAD@{1}\ngit log --oneline\ncat gradebook.py","summary":"The reflog is a local record of every commit HEAD has pointed to. It lets you find and restore commits that a reset or a deleted branch removed from the log.","notes":["HEAD@{0} is where you are now, HEAD@{1} is one move earlier, and so on.","git branch rescue HEAD@{1} is another way to recover: it puts a new branch on the lost commit.","The reflog is only on your computer, and Git deletes old entries after about 90 days."],"pitfall":"The reflog only has commits. Changes you never committed are not in it, so git reset --hard on uncommitted work cannot be undone.","keywords":["git reflog","recover commit","lost commit","HEAD@{1}","undo reset","deleted branch"],"stdin":"","output":"student@linux:~/project$ git log --oneline\n\u001b[33m0c23e33\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Print a letter grade\n\u001b[33m263c8aa\u001b[m Add quiz scores\n\u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ git reset --hard HEAD~1\nHEAD is now at 263c8aa Add quiz scores\nstudent@linux:~/project$ git log --oneline\n\u001b[33m263c8aa\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add quiz scores\n\u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ git reflog\n\u001b[33m263c8aa\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m HEAD@{0}: reset: moving to HEAD~1\n\u001b[33m0c23e33\u001b[m HEAD@{1}: commit: Print a letter grade\n\u001b[33m263c8aa\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m HEAD@{2}: commit: Add quiz scores\n\u001b[33m5cbfaad\u001b[m HEAD@{3}: commit (initial): Add gradebook script\nstudent@linux:~/project$ git reset --hard HEAD@{1}\nHEAD is now at 0c23e33 Print a letter grade\nstudent@linux:~/project$ git log --oneline\n\u001b[33m0c23e33\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Print a letter grade\n\u001b[33m263c8aa\u001b[m Add quiz scores\n\u001b[33m5cbfaad\u001b[m Add gradebook script\nstudent@linux:~/project$ cat gradebook.py\nscores = [88, 92, 79, 95]\naverage = sum(scores) / len(scores)\nprint(\"Average:\", average)\nprint(\"Letter:\", \"A\" if average >= 90 else \"B\")","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with three commits on main.","preview_height":null,"mode":"session","filename":null},"hooks":{"code":"# The team keeps its hook script in the repository. It blocks any commit that adds a TODO line.\ncat hooks/pre-commit\n# Git only runs hooks from .git/hooks, and only if the file is executable.\ncp hooks/pre-commit .git/hooks/pre-commit\nchmod +x .git/hooks/pre-commit\n# Try to commit a line with TODO in it.\necho '# TODO: print the highest score' >> gradebook.py\ngit add gradebook.py\ngit commit -m \"Plan the highest score\"\n# The hook exited with 1, so Git made no commit. The change is still staged.\ngit status\n# Replace the TODO with real code and commit again. The hook exits with 0 this time.\nsed -i 's/# TODO: print the highest score/print(\"Highest:\", max(scores))/' gradebook.py\ngit add gradebook.py\ngit commit -m \"Print the highest score\"\ngit log --oneline","summary":"A hook is a script Git runs at a set moment, such as right before a commit. A pre-commit hook that exits with a non-zero code stops the commit.","notes":["The file name picks the moment: pre-commit, commit-msg, pre-push, and others. .git/hooks has samples ending in .sample.","git clone does not copy .git/hooks. Teams keep hooks in the repository and copy them in, or set git config core.hooksPath hooks.","git commit --no-verify skips the pre-commit hook. Use it only when you know why the hook failed."],"pitfall":"A hook without execute permission does not run. Git prints a hint that the hook was ignored, and the commit goes through. Run chmod +x on it.","keywords":["git hooks","pre-commit",".git/hooks","chmod +x","--no-verify","core.hooksPath","automation"],"stdin":"","output":"student@linux:~/project$ cat hooks/pre-commit\n#!/bin/sh\n# Stop the commit if a staged line adds the word TODO.\n# --no-color keeps color codes out of the text that grep reads.\nif git diff --cached --no-color -U0 | grep -q '^+.*TODO'; then\n  echo \"pre-commit: remove TODO before you commit\"\n  exit 1\nfi\nstudent@linux:~/project$ cp hooks/pre-commit .git/hooks/pre-commit\nstudent@linux:~/project$ chmod +x .git/hooks/pre-commit\nstudent@linux:~/project$ echo '# TODO: print the highest score' >> gradebook.py\nstudent@linux:~/project$ git add gradebook.py\nstudent@linux:~/project$ git commit -m \"Plan the highest score\"\npre-commit: remove TODO before you commit\nstudent@linux:~/project$ git status\nOn branch main\nChanges to be committed:\n  (use \"git restore --staged <file>...\" to unstage)\n\t\u001b[32mmodified:   gradebook.py\u001b[m\n\nstudent@linux:~/project$ sed -i 's/# TODO: print the highest score/print(\"Highest:\", max(scores))/' gradebook.py\nstudent@linux:~/project$ git add gradebook.py\nstudent@linux:~/project$ git commit -m \"Print the highest score\"\n[main 547a229] Print the highest score\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git log --oneline\n\u001b[33m547a229\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Print the highest score\n\u001b[33maf70a5a\u001b[m Start gradebook with hooks","run":true,"shot":null,"shot_note":"","setup_note":"Starts in a repository with one commit. The folder hooks/ holds a pre-commit script that is not installed yet.","preview_height":null,"mode":"session","filename":null},"worktrees":{"code":"# Maya is on letter-grades with unfinished changes when a fix is needed on main.\ngit status\n# worktree add makes a second folder with its own branch. -b hotfix creates that branch from main.\ngit worktree add -b hotfix ../hotfix main\ngit worktree list\n# Work in the new folder. The unfinished changes in project are not touched.\ncd ../hotfix\nsed -i 's/socres/scores/' README.md\ngit commit -am \"Fix typo in README\"\n# Back in the first folder, the unfinished work is still there.\ncd ../project\ngit status\ngit log --oneline --graph --all\n# Remove the extra folder when you are done. The hotfix branch and its commit stay.\ngit worktree remove ../hotfix\ngit worktree list","summary":"A worktree is a second folder connected to the same repository, with a different branch checked out. You can work on two branches at once without stashing.","notes":["All worktrees share one history, so the hotfix commit is visible from project right away.","A branch can be checked out in only one worktree at a time.","Next, merge hotfix into main the usual way, or push it and open a pull request."],"pitfall":"Deleting the worktree folder with rm -r leaves Git thinking it still exists, and the branch stays locked. Use git worktree remove, or git worktree prune after an rm.","keywords":["git worktree","worktree add","worktree list","worktree remove","hotfix","two branches at once"],"stdin":"","output":"student@linux:~/project$ git status\nOn branch letter-grades\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   gradebook.py\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ git worktree add -b hotfix ../hotfix main\nPreparing worktree (new branch 'hotfix')\nHEAD is now at 5b1773b Add quiz scores\nstudent@linux:~/project$ git worktree list\n/home/student/project  b6d6297 [letter-grades]\n/home/student/hotfix   5b1773b [hotfix]\nstudent@linux:~/project$ cd ../hotfix\nstudent@linux:~/hotfix$ sed -i 's/socres/scores/' README.md\nstudent@linux:~/hotfix$ git commit -am \"Fix typo in README\"\n[hotfix 33f86e4] Fix typo in README\n 1 file changed, 1 insertion(+), 1 deletion(-)\nstudent@linux:~/hotfix$ cd ../project\nstudent@linux:~/project$ git status\nOn branch letter-grades\nChanges not staged for commit:\n  (use \"git add <file>...\" to update what will be committed)\n  (use \"git restore <file>...\" to discard changes in working directory)\n\t\u001b[31mmodified:   gradebook.py\u001b[m\n\nno changes added to commit (use \"git add\" and/or \"git commit -a\")\nstudent@linux:~/project$ git log --oneline --graph --all\n* \u001b[33m33f86e4\u001b[m\u001b[33m (\u001b[m\u001b[1;32mhotfix\u001b[m\u001b[33m)\u001b[m Fix typo in README\n\u001b[31m|\u001b[m * \u001b[33mb6d6297\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Add letter grade function\n\u001b[31m|\u001b[m\u001b[31m/\u001b[m  \n* \u001b[33m5b1773b\u001b[m\u001b[33m (\u001b[m\u001b[1;32mmain\u001b[m\u001b[33m)\u001b[m Add quiz scores\n* \u001b[33mff9d794\u001b[m Add gradebook script\nstudent@linux:~/project$ git worktree remove ../hotfix\nstudent@linux:~/project$ git worktree list\n/home/student/project  b6d6297 [letter-grades]","run":true,"shot":null,"shot_note":"","setup_note":"Starts on the branch letter-grades with one commit and an unfinished, uncommitted change to gradebook.py. README.md on main has a typo.","preview_height":null,"mode":"session","filename":null},"feature-workflow":{"code":"# Start a feature branch from main.\ngit switch -c letter-grades\nprintf 'print(\"Letter:\", \"A\" if average >= 90 else \"B\")\\n' >> gradebook.py\ngit commit -am \"Print a letter grade\"\n# Push the branch. -u links it to origin/letter-grades for later push and pull. --no-progress hides the transfer counters.\ngit push --no-progress -u origin letter-grades\n# On GitHub, Maya would open a pull request here. Jordan reviews it and merges it into main.\ncd ../jordan\ngit fetch --no-progress\ngit merge --no-ff --no-edit origin/letter-grades\ngit push --no-progress\n# Back in Maya's folder, update main with the merged work.\ncd ../project\ngit switch main\ngit pull --no-progress\ngit log --oneline --graph --all\n# The feature is in main, so delete the branch here and on origin.\ngit branch -d letter-grades\ngit push origin --delete letter-grades","summary":"In a feature branch workflow, every change goes on its own branch, gets pushed and reviewed, and is merged into main. Then everyone pulls main.","notes":["On GitHub, the review and merge happen in a pull request: it shows the branch's diff, collects comments, and has a Merge button that does what Jordan's merge and push do here.","--no-ff makes a merge commit even when a fast-forward is possible, which is what GitHub's default merge button does. It records that the feature came in as one unit.","Keep main working at all times. Unfinished work lives on branches until it is reviewed."],"pitfall":"Starting a new branch from an old main leads to conflicts later. Run git switch main and git pull before git switch -c.","keywords":["feature branch","pull request","PR","code review","git push -u","workflow","github flow","--no-ff"],"stdin":"","output":"student@linux:~/project$ git switch -c letter-grades\nSwitched to a new branch 'letter-grades'\nstudent@linux:~/project$ printf 'print(\"Letter:\", \"A\" if average >= 90 else \"B\")\\n' >> gradebook.py\nstudent@linux:~/project$ git commit -am \"Print a letter grade\"\n[letter-grades 1952726] Print a letter grade\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git push --no-progress -u origin letter-grades\nTo /home/student/gradebook.git\n * [new branch]      letter-grades -> letter-grades\nbranch 'letter-grades' set up to track 'origin/letter-grades'.\nstudent@linux:~/project$ cd ../jordan\nstudent@linux:~/jordan$ git fetch --no-progress\nFrom /home/student/gradebook\n * [new branch]      letter-grades -> origin/letter-grades\nstudent@linux:~/jordan$ git merge --no-ff --no-edit origin/letter-grades\nMerge made by the 'ort' strategy.\n gradebook.py | 1 \u001b[32m+\u001b[m\n 1 file changed, 1 insertion(+)\nstudent@linux:~/jordan$ git push --no-progress\nTo /home/student/gradebook.git\n   99d8028..86799f5  main -> main\nstudent@linux:~/jordan$ cd ../project\nstudent@linux:~/project$ git switch main\nSwitched to branch 'main'\nYour branch is up to date with 'origin/main'.\nstudent@linux:~/project$ git pull --no-progress\nFrom /home/student/gradebook\n   99d8028..86799f5  main       -> origin/main\nUpdating 99d8028..86799f5\nFast-forward\n gradebook.py | 1 \u001b[32m+\u001b[m\n 1 file changed, 1 insertion(+)\nstudent@linux:~/project$ git log --oneline --graph --all\n*   \u001b[33m86799f5\u001b[m\u001b[33m (\u001b[m\u001b[1;36mHEAD\u001b[m\u001b[33m -> \u001b[m\u001b[1;32mmain\u001b[m\u001b[33m, \u001b[m\u001b[1;31morigin/main\u001b[m\u001b[33m, \u001b[m\u001b[1;31morigin/HEAD\u001b[m\u001b[33m)\u001b[m Merge remote-tracking branch 'origin/letter-grades'\n\u001b[31m|\u001b[m\u001b[32m\\\u001b[m  \n\u001b[31m|\u001b[m * \u001b[33m1952726\u001b[m\u001b[33m (\u001b[m\u001b[1;31morigin/letter-grades\u001b[m\u001b[33m, \u001b[m\u001b[1;32mletter-grades\u001b[m\u001b[33m)\u001b[m Print a letter grade\n\u001b[31m|\u001b[m\u001b[31m/\u001b[m  \n* \u001b[33m99d8028\u001b[m Add quiz scores\n* \u001b[33m610f512\u001b[m Add gradebook script\nstudent@linux:~/project$ git branch -d letter-grades\nDeleted branch letter-grades (was 1952726).\nstudent@linux:~/project$ git push origin --delete letter-grades\nTo /home/student/gradebook.git\n - [deleted]         letter-grades","run":true,"shot":null,"shot_note":"","setup_note":"Starts in Maya's clone of ../gradebook.git, on main. Her teammate Jordan has his own clone in ../jordan.","preview_height":null,"mode":"session","filename":null}}}};
